)

// ErrorCode is a stable machine-readable run-control failure category.
type ErrorCode string

const (
	CodeInvalidArgument   ErrorCode = "invalid_argument"
	CodeNotFound          ErrorCode = "not_found"
	CodeConflict          ErrorCode = "conflict"
	CodeStaleFence        ErrorCode = "stale_fence"
	CodeTerminal          ErrorCode = "terminal"
	CodeUnavailable       ErrorCode = "unavailable"
	CodeBusy              ErrorCode = "busy"
	CodePermission        ErrorCode = "permission_denied"
	CodeCorrupt           ErrorCode = "corrupt"
	CodeUnsupportedSchema ErrorCode = "unsupported_schema"
	CodeInvariant         ErrorCode = "invariant_violation"
	CodeQuota             ErrorCode = "quota_exceeded"
)

var (
	ErrInvalidArgument   = &Error{Code: CodeInvalidArgument}
	ErrNotFound          = &Error{Code: CodeNotFound}
	ErrConflict          = &Error{Code: CodeConflict}
	ErrStaleFence        = &Error{Code: CodeStaleFence}
	ErrTerminal          = &Error{Code: CodeTerminal}
	ErrUnavailable       = &Error{Code: CodeUnavailable}
	ErrBusy              = &Error{Code: CodeBusy}
	ErrPermission        = &Error{Code: CodePermission}
	ErrCorrupt           = &Error{Code: CodeCorrupt}
	ErrUnsupportedSchema = &Error{Code: CodeUnsupportedSchema}
	ErrInvariant         = &Error{Code: CodeInvariant}
	ErrQuota             = &Error{Code: CodeQuota}
)

// Error is safe to classify without parsing driver or filesystem messages.
// Cause is retained for local operator diagnostics but is never a public DTO.
type Error struct {
	Code      ErrorCode
	Operation string
	RunID     RunID
	Message   string
	Retryable bool
	Cause     error
}

func (e *Error) Error() string {
	if e == nil {
		return "<nil>"
	}
	message := e.Message
	if message == "" {
		message = string(e.Code)
	}
	if e.Operation == "" {
		return message
	}
	return fmt.Sprintf("%s: %s", e.Operation, message)
}

func (e *Error) Unwrap() error {
	if e == nil {
		return nil
	}
	return e.Cause
}

func (e *Error) Is(target error) bool {
	var other *Error
	return errors.As(target, &other) && e != nil && e.Code != "" && e.Code == other.Code
}

func wrapError(code ErrorCode, operation, message string, retryable bool, cause error) error {
	return &Error{Code: code, Operation: operation, Message: message, Retryable: retryable, Cause: cause}
}

func runError(code ErrorCode, operation string, runID RunID, message string, retryable bool, cause error) error {
	return &Error{Code: code, Operation: operation, RunID: runID, Message: message, Retryable: retryable, Cause: cause}
}

func invalidField(field, message string) error {
	return wrapError(CodeInvalidArgument, "validate", field+" "+message, false, nil)
}

package runcontrol

import (
	"context"
	"time"
)

// Clock is injected so lifecycle tests do not depend on wall-clock timing.
type Clock interface {
	Now() time.Time
}

type WallClock struct{}

func (WallClock) Now() time.Time { return time.Now().UTC() }

// ProcessProbe resolves an exact process-birth identity. Implementations must
// report uncertainty instead of treating PID presence as ownership proof.
type ProcessProbe interface {
	Probe(context.Context, int) (ProcessIdentity, error)
}

type LogLevel string

const (
	LogDebug LogLevel = "debug"
	LogInfo  LogLevel = "info"
	LogWarn  LogLevel = "warn"
	LogError LogLevel = "error"
)

type LogField struct {
	Key   string
	Value string
}

type Logger interface {
	Log(context.Context, LogLevel, string, ...LogField)
}

// Notifier is a best-effort latency optimization. A notification never makes
// an event authoritative; observers always recover from Repository.Events.
type Notifier interface {
	Notify(RunID, uint64)
}

// Repository is the narrow durable authority used by the run-control service.
// Product workflow state and runtime supervision are intentionally absent.
type Repository interface {
	Accept(context.Context, Acceptance) (Snapshot, error)
	ResolveOperationAlias(context.Context, string) (Snapshot, error)
	Claim(context.Context, Claim) (Attempt, Snapshot, error)
	Snapshot(context.Context, RunID) (Snapshot, error)
	List(context.Context, Query) (Page, error)
	Append(context.Context, Fence, EventDraft) (Event, Snapshot, error)
	Heartbeat(context.Context, Fence, time.Duration) (Snapshot, error)
	RequestCancellation(context.Context, RunID, string) (Snapshot, bool, error)
	AcknowledgeCancellation(context.Context, Fence) (Snapshot, bool, error)
	ProposeTerminal(context.Context, Fence, TerminalProposal) (Snapshot, bool, error)
	Events(context.Context, RunID, uint64, int) ([]Event, error)
	Reconcile(context.Context, ProcessProbe, ReconcileOptions) (ReconcileReport, error)
	Compact(context.Context, int) (CompactionReport, error)
	Health(context.Context) (Health, error)
	Close() error
}

// Control is the adapter-neutral service capability. Keeping this interface
// separate permits app composition to decorate durable operations without
// exposing SQL or transport details.
type Control interface {
	Repository
}

